/**
 * Reference QR symbols, from an encoder that is not this one.
 *
 * Generated with the `qrcode` npm package at version 1.5.4, which is the most
 * widely used JavaScript QR encoder and is therefore the closest thing to "a code
 * every scanner reads" that is available without a camera. It is deliberately
 * **not** a dependency of anything: the matrices are baked in here so that the
 * check is against somebody else's arithmetic rather than against a decoder
 * written beside the encoder from the same mental model -- which is the failure
 * this repository already records for the canvas diff's model terminal, and which
 * a round trip through my own reader would reproduce exactly.
 *
 * Each entry is the whole symbol: the version and the mask the reference encoder
 * chose, and every module of the result. A disagreement anywhere -- a generator
 * polynomial, a block split, an interleave, a mask penalty, a format bit -- shows
 * up as a different row.
 *
 * The reference is asked for **one segment** in the mode this encoder would pick,
 * which is what makes it a like-for-like comparison: `qrcode` splits a payload
 * into a cheapest sequence of segments and this encoder deliberately does not, so
 * comparing against its default path would be comparing two different encodings
 * of one string. What that decision costs is not left as a claim either --
 * `QR_SEGMENTS` below is the same payloads through both paths.
 *
 * The four largest payloads are split between the first two tables for size
 * alone: all four of their matrices come to 180 kB of fixture and two of them is
 * 95. Which two is not arbitrary -- the two kept whole are the 14-bit count
 * indicator at version 40 and the 81-block interleave at level H, which are the
 * two things no smaller symbol exercises.
 *
 * To regenerate, in a scratch directory outside this repository:
 *
 * ```sh
 * npm install qrcode@1.5.4
 * node -e "const QR=require('qrcode');const q=QR.create([{data:'01234567',mode:'numeric'}],{errorCorrectionLevel:'M'});console.log(q.version,q.maskPattern)"
 * ```
 */

/** One reference symbol, whole. */
export interface QrVector {
	/** The level it was encoded at. */
	readonly ecc: 'L' | 'M' | 'Q' | 'H';
	/** The mask the reference encoder chose. */
	readonly mask: number;
	/** The mode the reference was asked for, which is the one this encoder picks. */
	readonly mode: 'numeric' | 'alphanumeric' | 'byte';
	/** The modules, one string per row, `#` for dark and `.` for light. */
	readonly rows: readonly string[];
	/** What was encoded. */
	readonly text: string;
	/** The version the reference encoder chose. */
	readonly version: number;
	/** Why this one is in the list. */
	readonly why: string;
}

/** A payload whose version the reference encoder agrees about. */
export interface QrSizeVector {
	/** The level it was encoded at. */
	readonly ecc: 'L' | 'M' | 'Q' | 'H';
	/** The mode the reference was asked for. */
	readonly mode: 'numeric' | 'alphanumeric' | 'byte';
	/** What was encoded. */
	readonly text: string;
	/** The version the reference encoder chose. */
	readonly version: number;
	/** Why this one is in the list. */
	readonly why: string;
}

/** What one segment costs against a reference encoder that splits them. */
export interface QrSegmentCost {
	/** The level both were encoded at. */
	readonly ecc: 'L' | 'M' | 'Q' | 'H';
	/** The version the reference's own segment optimiser reached. */
	readonly mixed: number;
	/** The version one segment reaches, which is what this encoder does. */
	readonly single: number;
	/** What was encoded. */
	readonly text: string;
	/** Why this one is in the list. */
	readonly why: string;
}

